struct buf { size_t len; char data[]; };
struct buf_h { struct buf *p; };
static void buf_h_drop(struct buf_h *h) { if (h->p) { free(h->p); h->p = NULL; } }
static struct buf_h buf_own(size_t n) {
    struct buf_h h = { malloc(sizeof(struct buf) + n) };
    return h;
}
int use(void) {
    struct buf_h __attribute__((cleanup(buf_h_drop))) h = buf_own(4096);
    if (!h.p) return -1;
    return process(h.p);
}   /* release runs on every return path */
